<script setup>
import {computed,ref,watch} from 'vue';
const props=defineProps({page:{type:Number,default:1},pageSize:{type:Number,default:20},total:{type:Number,default:null},loading:Boolean});
const emit=defineEmits(['change']);
const pages=computed(()=>props.total==null?null:Math.max(1,Math.ceil(props.total/props.pageSize))),draft=ref(props.page);
watch(()=>props.page,value=>draft.value=value);
function move(value){if(props.loading||pages.value==null)return;const next=Math.max(1,Math.min(pages.value,Math.trunc(Number(value)||1)));draft.value=next;if(next!==props.page)emit('change',{page:next,pageSize:props.pageSize});}
</script>
<template><nav class="mobile-list-footer" aria-label="分页"><div class="mobile-pagination-summary"><span>{{total==null?'数量待更新':`共 ${total} 条`}}</span><select :value="pageSize" aria-label="每页条数" :disabled="loading" @change="emit('change',{page:1,pageSize:Number($event.target.value)})"><option :value="20">每页20条</option><option :value="50">每页50条</option><option :value="100">每页100条</option></select></div><div class="mobile-pagination-pages"><el-button :disabled="loading||page<=1" @click="move(page-1)">上一页</el-button><label>第 <input v-model="draft" aria-label="当前页" type="number" inputmode="numeric" min="1" :max="pages||1" :disabled="loading||pages==null" @change="move(draft)" @keyup.enter="move(draft)"> / {{pages??'—'}} 页</label><el-button :disabled="loading||pages==null||page>=pages" @click="move(page+1)">下一页</el-button></div></nav></template>
<style scoped>.mobile-list-footer{display:grid;gap:8px;padding:10px 0 0;border-top:1px solid var(--el-border-color-light);background:var(--erp-detail-surface-alt,#f4f7fb);font-size:12px;flex:none}.mobile-pagination-summary,.mobile-pagination-pages{display:flex;align-items:center;justify-content:space-between;gap:8px}.mobile-pagination-pages label{display:flex;align-items:center;gap:4px;white-space:nowrap}.mobile-pagination-pages input{width:48px;min-width:0;text-align:center;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-bg-color);color:var(--el-text-color-primary);padding:5px 2px}.mobile-pagination-summary select{max-width:135px;min-height:32px;border:1px solid var(--el-border-color);background:var(--el-bg-color);border-radius:6px;color:var(--el-text-color-primary)}.el-button{margin:0}</style>
